import time
import urllib.request
from urllib.error import URLError, HTTPError

class ClientError(Exception):
    pass

class RateLimitError(Exception):
    pass

class ServerError(Exception):
    pass

class ConnectionError(Exception):
    pass

class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path):
        try:
            req = urllib.request.Request(self.base_url + path, timeout=self.timeout)
            response = urllib.request.urlopen(req)
            return response.read().decode('utf-8')
        except HTTPError as e:
            if e.code == 429:
                self._retry_rate_limit()
            elif e.code == 5xx:
                self._retry_server_error()
            else:
                raise ClientError("HTTP error occurred: " + str(e))
        except URLError as e:
            self._retry_connection_error()
            raise ConnectionError("Connection error occurred: " + str(e))
        except Exception as e:
            raise ClientError("An error occurred: " + str(e))

    def _retry_rate_limit(self):
        retries = 0
        while retries < 3:
            try:
                return
            except HTTPError as e:
                if e.code == 429:
                    raise RateLimitError("Rate limit exceeded after retries")
                time.sleep(0.5)
            retries += 1
            time.sleep(1)

    def _retry_server_error(self):
        retries = 0
        while retries < 1:
            try:
                return
            except ServerError:
                time.sleep(1)
            retries += 1

    def _retry_connection_error(self):
        retries = 0
        while retries < 1:
            try:
                return
            except URLError:
                time.sleep(1)
            retries += 1
